<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api} from '../api'
import {questionStages,formatDate} from '../utils/assignments'
import {auth} from '../composables/auth'
import MembersView from './MembersView.vue'
const route=useRoute(),mode=computed(()=>route.meta.adminMode || 'overview'),overview=ref(null),cases=ref([]),courses=ref([]),form=ref(null),templates=ref([]),templateBody=ref(''),settings=ref(null),audit=ref([]),error=ref(''),notice=ref(''),busy=ref(false),newCourse=ref(false),courseForm=ref({code:'',title:'',termCode:''}),members=ref([]),accounts=ref([]),memberForm=ref({userId:'',courseRole:'student'}),selectedCourse=ref(''),formBaseline=ref(''),templateBaseline=ref(''),settingsBaseline=ref('')
const sections=computed(()=>[{key:'overview',path:'/admin',label:'管理後台首頁',id:'A1'},{key:'accounts',path:'/admin/accounts',label:'帳號管理',id:'A2'},{key:'cases',path:'/admin/cases',label:'案例維護',id:'A3'},{key:'references',path:'/admin/references',label:'標準答案／重點清單',id:'A4'},{key:'templates',path:'/admin/templates',label:'AI 回饋模板',id:'A5'},{key:'settings',path:'/admin/settings',label:'系統參數＋稽核軌跡',id:'A6'}].filter(s=>['cases','references'].includes(s.key)?auth.user.canTeach:auth.user.role==='Administrator'))
const current=computed(()=>sections.value.find(s=>s.key===mode.value))
async function load(){if(mode.value==='overview')overview.value=await api('/studio/admin/overview');if(['cases','references'].includes(mode.value)){[cases.value,courses.value]=await Promise.all([api('/studio/admin/cases'),api('/studio/admin/courses')]);if(route.query.course)cases.value=cases.value.filter(c=>c.courseId===route.query.course)}if(mode.value==='templates'){templates.value=await api('/studio/admin/templates');templateBody.value=templates.value[0]?.body||'';templateBaseline.value=templateBody.value}if(mode.value==='settings'){[settings.value,audit.value]=await Promise.all([api('/studio/admin/settings'),api('/studio/admin/audit')]);settingsBaseline.value=JSON.stringify(settings.value)}}
async function run(action){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function edit(id){if(form.value && caseDirty.value && !confirm('確定放棄尚未儲存的案例修改？'))return;await run(async()=>{form.value=id?await api('/studio/admin/cases/'+id):{courseId:courses.value.find(c=>c.id===route.query.course)?.id||courses.value[0]?.id||'',title:'',material:'',prompts:Object.fromEntries(questionStages.map(s=>[s.key,`請根據案例分析${s.label}，區分事實、證據與推論。`])),referencePoints:Object.fromEntries(questionStages.map(s=>[s.key,''])),draftVersionId:null};form.value.expectedDraftVersionId=form.value.draftVersionId;formBaseline.value=JSON.stringify(form.value)})}
async function saveCase(){await run(async()=>{const saved=await api('/studio/admin/cases'+(form.value.id?'/'+form.value.id:''),{method:form.value.id?'PUT':'POST',body:form.value});form.value=await api('/studio/admin/cases/'+saved.id);form.value.expectedDraftVersionId=form.value.draftVersionId;formBaseline.value=JSON.stringify(form.value);await load();notice.value='新案例版本已儲存為草稿。發布前學生看不到新內容。'})}
async function publish(){if(caseDirty.value){error.value='請先儲存案例修改再發布。';return}if(!confirm('發布此版本後，所屬課程學生可開始作答；先前作答仍保留原案例版本。確定發布？'))return;await run(async()=>{await api(`/studio/admin/cases/${form.value.id}/publish`,{method:'POST',body:{expectedDraftVersionId:form.value.draftVersionId}});await load();notice.value='案例版本已發布。'})}
async function saveTemplate(){await run(async()=>{await api('/studio/admin/templates',{method:'POST',body:{body:templateBody.value,expectedVersion:templates.value[0]?.versionNo}});await load();notice.value='回饋模板新版本已啟用；既有回饋保留原模板版本。'})}
async function saveSettings(){await run(async()=>{await api('/studio/admin/settings',{method:'PUT',body:{...settings.value,expectedVersion:settings.value.version}});await load();notice.value='案例回饋系統參數已更新。'})}
async function createCourse(){await run(async()=>{await api('/courses',{method:'POST',body:courseForm.value});newCourse.value=false;courseForm.value={code:'',title:'',termCode:''};await load();notice.value='課程已建立，請至帳號管理設定課程成員。'})}
async function loadMembers(){await run(async()=>{members.value=selectedCourse.value?await api(`/courses/${selectedCourse.value}/members`):[]})}
async function enroll(){await run(async()=>{await api(`/courses/${selectedCourse.value}/members`,{method:'POST',body:memberForm.value});members.value=await api(`/courses/${selectedCourse.value}/members`);notice.value='課程成員已更新。'})}
const caseDirty=computed(()=>form.value && JSON.stringify(form.value)!==formBaseline.value)
const dirty=computed(()=>caseDirty.value || (mode.value==='templates' && templateBody.value!==templateBaseline.value) || (mode.value==='settings' && settings.value && JSON.stringify(settings.value)!==settingsBaseline.value))
function guard(){return !dirty.value || confirm('管理頁面有尚未儲存的修改，確定離開？')}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
function unload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
onMounted(()=>run(load))
</script>
<template><section class="page-heading"><div><p class="eyebrow">{{current.id}} · ADMINISTRATION</p><h1>{{current.label}}</h1><p class="muted">平台管理權限與課程角色分開；案例維護只限本人任教課程。</p></div></section><RouterLink v-if="route.query.course" :to="`/courses/${route.query.course}?section=cases`" class="back-link">← 返回所選課程</RouterLink><nav class="course-navigation" aria-label="管理後台功能"><RouterLink v-for="s in sections" :key="s.key" :to="s.path" :class="{active:mode===s.key}">{{s.id}} {{s.label}}</RouterLink></nav><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><section v-if="mode==='overview' && overview" class="surface form-surface"><h2>管理概況</h2><div class="gradebook-summary"><div><span>帳號</span><strong>{{overview.accounts}}</strong></div><div><span>案例</span><strong>{{overview.cases}}</strong></div><div><span>已發布案例</span><strong>{{overview.published}}</strong></div><div><span>正式提交</span><strong>{{overview.submitted}}</strong></div></div><p>先建立課程與師生成員，再維護案例原文、四階段結構提示與重點清單，確認後發布。</p></section><template v-if="mode==='accounts'"><MembersView /></template><template v-if="mode==='cases' || mode==='references'"><section class="surface form-surface"><div class="section-title"><h2>{{mode==='cases'?'案例素材與結構提示':'標準答案／重點清單維護'}}</h2><button v-if="mode==='cases'" class="button primary" :disabled="busy || !courses.length" @click="edit()">新增案例</button></div><p class="field-hint">案例需關聯課程。重點清單僅供管理與 AI 核對，學生端不提供原始標準答案。</p><button v-if="mode==='cases' && auth.user.canCreateCourses" class="button secondary" @click="newCourse=!newCourse">建立課程</button><form v-if="newCourse" @submit.prevent="createCourse"><label>課程代碼<input v-model="courseForm.code" required maxlength="40" /></label><label>課程名稱<input v-model="courseForm.title" required maxlength="200" /></label><label>學期<input v-model="courseForm.termCode" required maxlength="40" /></label><button class="button primary" :disabled="busy">儲存課程</button></form><article v-for="c in cases" :key="c.id" :data-case-id="c.id" class="question-editor"><button class="text-button" :disabled="busy" @click="edit(c.id)">{{c.title}}</button><p>{{c.courseTitle}} · 最新 v{{c.versionNo}} · {{c.published?'已有發布版本':'未發布'}}</p></article><p v-if="!cases.length" class="empty-inline">目前尚無新案例。舊課程資料保留，但不會自動轉為已發布案例。</p></section><section v-if="form" class="surface form-surface"><form @submit.prevent="saveCase"><fieldset :disabled="busy"><label>所屬課程<select aria-label="所屬課程" v-model="form.courseId" :disabled="!!form.id" required><option v-for="c in courses" :key="c.id" :value="c.id">{{c.code}} · {{c.title}}</option></select></label><label>案例名稱<input v-model="form.title" required maxlength="200" :readonly="mode==='references'" /></label><label v-if="mode==='cases'">案例原文<textarea v-model="form.material" required maxlength="24000" rows="12"></textarea></label><section v-for="s in questionStages" :key="s.key" class="question-editor"><h3>{{s.label}}</h3><label v-if="mode==='cases'">結構提示<textarea :aria-label="`${s.label} 結構提示`" v-model="form.prompts[s.key]" required maxlength="8000" rows="3"></textarea></label><label v-else>標準答案／重點清單<textarea :aria-label="`${s.label} 重點清單`" v-model="form.referencePoints[s.key]" maxlength="8000" rows="5"></textarea></label></section><div class="studio-actions"><button class="button primary">儲存新版本草稿</button><button v-if="form.id" type="button" class="button secondary" :disabled="caseDirty" @click="publish">發布已儲存版本</button><button type="button" class="button secondary" @click="form=null">關閉</button></div><p class="field-hint">發布的是最後已儲存版本，請先儲存修改再發布。既有學習紀錄綁定原案例版本。</p></fieldset></form></section></template><section v-if="mode==='templates'" class="surface form-surface"><h2>文字回饋風格模板</h2><p class="field-hint">模板控制回饋風格。禁止分數、只依案例證據與不代寫等固定規則由系統保留，不能透過模板移除。</p><form @submit.prevent="saveTemplate"><label>回饋模板<textarea v-model="templateBody" required maxlength="12000" rows="10"></textarea></label><button class="button primary" :disabled="busy">儲存並啟用新模板版本</button></form><details><summary>歷史版本</summary><article v-for="t in templates" :key="t.id"><h3>v{{t.versionNo}} · {{formatDate(t.createdAt)}}</h3><p class="studio-prose">{{t.body}}</p></article></details></section><template v-if="mode==='settings' && settings"><section class="surface form-surface"><h2>案例 AI 回饋參數</h2><p class="muted">模型 {{settings.model}} · {{settings.profile}}（目前啟動設定，唯讀）</p><form @submit.prevent="saveSettings"><label class="choice-label"><input v-model="settings.feedbackEnabled" type="checkbox" />啟用案例文字回饋</label><label>回饋逾時秒數<input v-model.number="settings.timeoutSeconds" type="number" min="5" max="300" required /></label><label>每答案版本最多請求次數<input v-model.number="settings.maxRequestsPerRevision" type="number" min="1" max="10" required /></label><button class="button primary" :disabled="busy">儲存系統參數</button></form><p class="field-hint">實際逾時另受部署端 {{settings.deploymentTimeoutSeconds}} 秒上限限制。僅影響新案例回饋。模型、端點與各模型相容性設定沿用部署配置，不在此頁變更。</p></section><section class="surface form-surface"><h2>最近 200 筆稽核軌跡</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>時間</th><th>操作人員</th><th>動作</th><th>對象</th></tr></thead><tbody><tr v-for="row in audit" :key="row.id"><td>{{formatDate(row.occurredAt)}}</td><td>{{row.actor}}</td><td>{{row.action}}</td><td>{{row.entityType}} · {{row.entityId}}</td></tr></tbody></table></div><p class="field-hint">不提供作答全文、原始模型回應、thinking 或連線憑證。</p></section></template></template>

